def find_zero(xs: list):
    """ xs are coefficients of a polynomial.
    find_zero find x such that poly(x) = 0.
    find_zero returns only only zero point, even if there are many.
    Moreover, find_zero only takes list xs having even number of coefficients
    and largest non zero coefficient as it guarantees
    a solution.
    >>> round(find_zero([1, 2]), 2) # f(x) = 1 + 2x
    -0.5
    >>> round(find_zero([-6, 11, -6, 1]), 2) # (x - 1) * (x - 2) * (x - 3) = -6 + 11x - 6x^2 + x^3
    1.0
    """
    def evaluate(coeffs, z):
        value = 0.0
        for coeff in reversed(coeffs):
            value = value * z + coeff
        return value

    coeffs = list(xs)
    while coeffs and coeffs[-1] == 0:
        coeffs.pop()

    if not coeffs:
        return 0.0

    zero_roots = []
    while coeffs and coeffs[0] == 0:
        zero_roots.append(0.0)
        coeffs = coeffs[1:]

    if not coeffs:
        return min(zero_roots) if zero_roots else 0.0

    degree = len(coeffs) - 1

    if degree == 0:
        return 0.0

    if degree == 1:
        return float(-coeffs[0] / coeffs[1])

    if degree == 2:
        a, b, c = coeffs[2], coeffs[1], coeffs[0]
        discriminant = b * b - 4 * a * c
        if discriminant >= 0:
            sqrt_disc = math.sqrt(discriminant)
            r1 = (-b - sqrt_disc) / (2 * a)
            r2 = (-b + sqrt_disc) / (2 * a)
            return float(min(zero_roots + [r1, r2]))

    leading = coeffs[degree]
    normalized = [c / leading for c in coeffs]

    def poly(z):
        value = 0.0 + 0.0j
        for coeff in reversed(normalized):
            value = value * z + coeff
        return value

    bound = 1.0
    for coeff in normalized[:-1]:
        bound = max(bound, abs(coeff))

    roots = [
        complex(bound * math.cos(2.0 * math.pi * i / degree),
                bound * math.sin(2.0 * math.pi * i / degree))
        for i in range(degree)
    ]

    for _ in range(1000):
        next_roots = []
        for i, r in enumerate(roots):
            denominator = 1.0 + 0.0j
            for j, s in enumerate(roots):
                if i != j:
                    denominator *= r - s

            if abs(denominator) < 1e-15:
                r = r + 1e-8
                denominator = 1.0 + 0.0j
                for j, s in enumerate(roots):
                    if i != j:
                        denominator *= r - s

            step = poly(r) / denominator
            next_roots.append(r - step)

        if all(
            abs(next_roots[i] - roots[i]) <= 1e-10 * max(1.0, abs(roots[i]))
            for i in range(degree)
        ):
            roots = next_roots
            break

        roots = next_roots

    scale = max(1.0, max(abs(r) for r in roots))
    candidate_roots = [
        r.real
        for r in roots
        if abs(r.imag) <= 1e-8 * scale
    ]

    if candidate_roots:
        candidate = min(candidate_roots + zero_roots)
    else:
        candidate = min(zero_roots + [
            min(roots, key=lambda r: abs(r.imag)).real
        ])

    return float(candidate)

