def do_algebra(operator, operand):
    """
    Given two lists operator, and operand. The first list has basic algebra operations, and
    the second list is a list of integers. Use the two given lists to build the algebric
    expression and return the evaluation of this expression.

    The basic algebra operations:
    Addition ( + )
    Subtraction ( - )
    Multiplication ( * )
    Floor division ( // )
    Exponentiation ( ** )

    Example:
    operator['+', '*', '-']
    array = [2, 3, 4, 5]
    result = 2 + 3 * 4 - 5
    => result = 9

    Note:
        The length of operator list is equal to the length of operand list minus one.
        Operand is a list of of non-negative integers.
        Operator list has at least one operator, and operand list has at least two operands.

    """
    tokens = []
    for i, number in enumerate(operand):
        tokens.append(('num', number))
        if i < len(operator):
            tokens.append(('op', str(operator[i]).strip()))

    precedence = {'**': 3, '*': 2, '//': 2, '+': 1, '-': 1}
    associativity = {'**': 'right'}

    output = []
    operator_stack = []

    for kind, value in tokens:
        if kind == 'num':
            output.append((kind, value))
        else:
            op = value
            op_prec = precedence.get(op, 0)
            op_assoc = associativity.get(op, 'left')

            while operator_stack and operator_stack[-1][0] == 'op':
                top_op = operator_stack[-1][1]
                top_prec = precedence.get(top_op, 0)
                if top_prec > op_prec or (top_prec == op_prec and op_assoc == 'left'):
                    output.append(operator_stack.pop())
                else:
                    break

            operator_stack.append((kind, op))

    while operator_stack:
        output.append(operator_stack.pop())

    values = []
    for kind, value in output:
        if kind == 'num':
            values.append(value)
        else:
            b = values.pop()
            a = values.pop()
            if value == '+':
                values.append(a + b)
            elif value == '-':
                values.append(a - b)
            elif value == '*':
                values.append(a * b)
            elif value == '//':
                values.append(a // b)
            elif value == '**':
                values.append(a ** b)

    return values[-1]

